{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not configured to use Customer Supplied Encryption Keys (CSEK). Without CSEK, the data is encrypted using Google-managed keys, which may not meet organizational compliance or security requirements."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name       = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to configure the PubSub topic to use a Customer Supplied Encryption Key (CSEK)."
}
